1	package server
2	
3	import (
4		"bytes"
5		"encoding/base64"
6		"encoding/json"
7		"errors"
8		"io"
9		"mime"
10		"net/http"
11		"sort"
12		"strconv"
13	)
14	
15	// bundleMediaType is the only media type accepted and produced by the
16	// bundle endpoints.
17	const bundleMediaType = "application/vnd.cidvault.bundle+json"
18	
19	// bundleVersion is the only bundle format version this server understands.
20	const bundleVersion = 1
21	
22	// maxBundleSize bounds the wire size of an import body. A bundle carrying a
23	// maximum-size object is dominated by the Base64 expansion of its blocks;
24	// the slack covers JSON framing, identifiers and whitespace.
25	const maxBundleSize = 4*(MaxObjectSize/3+1) + 1<<20
26	
27	// bundleRoot mirrors the manifest of the exported object.
28	type bundleRoot struct {
29		CID       string   `json:"cid"`
30		Size      int      `json:"size"`
31		ChunkSize int      `json:"chunkSize"`
32		Chunks    []string `json:"chunks"`
33	}
34	
35	// bundleBlock carries one unique block with its raw bytes in standard
36	// RFC 4648 Base64.
37	type bundleBlock struct {
38		CID  string `json:"cid"`
39		Data string `json:"data"`
40	}
41	
42	// bundleDocument is the JSON body of GET /v1/bundles/{cid}.
43	type bundleDocument struct {
44		Version int           `json:"version"`
45		Root    bundleRoot    `json:"root"`
46		Blocks  []bundleBlock `json:"blocks"`
47	}
48	
49	// getBundle handles GET /v1/bundles/{cid}.
50	func (s *store) getBundle(w http.ResponseWriter, r *http.Request) {
51		if r.Method != http.MethodGet {
52			w.Header().Set("Allow", http.MethodGet)
53			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
54			return
55		}
56		obj := s.lookupObject(w, r)
57		if obj == nil {
58			return
59		}
60		dataByCID := make(map[string][]byte, len(obj.cids))
61		for i, c := range obj.cids {
62			dataByCID[c] = obj.chunks[i]
63		}
64		cids := make([]string, 0, len(dataByCID))
65		for c := range dataByCID {
66			cids = append(cids, c)
67		}
68		sort.Strings(cids)
69		blocks := make([]bundleBlock, 0, len(cids))
70		for _, c := range cids {
71			blocks = append(blocks, bundleBlock{
72				CID:  c,
73				Data: base64.StdEncoding.EncodeToString(dataByCID[c]),
74			})
75		}
76		w.Header().Set("Content-Type", bundleMediaType)
77		_ = json.NewEncoder(w).Encode(bundleDocument{
78			Version: bundleVersion,
79			Root: bundleRoot{
80				CID:       obj.cid,
81				Size:      obj.size,
82				ChunkSize: ChunkSize,
83				Chunks:    obj.cids,
84			},
85			Blocks: blocks,
86		})
87	}
88	
89	// bundleRootJSON is the strictly decoded root section of an import body.
90	// Pointer fields distinguish a missing key from a zero value; numbers stay
91	// raw so quoted strings are rejected as type errors.
92	type bundleRootJSON struct {
93		CID       *string          `json:"cid"`
94		Size      *json.RawMessage `json:"size"`
95		ChunkSize *json.RawMessage `json:"chunkSize"`
96		Chunks    *[]string        `json:"chunks"`
97	}
98	
99	// bundleBlockJSON is one strictly decoded block entry of an import body.
100	type bundleBlockJSON struct {
101		CID  *string `json:"cid"`
102		Data *string `json:"data"`
103	}
104	
105	// bundleJSON is the strictly decoded import body.
106	type bundleJSON struct {
107		Version *json.RawMessage   `json:"version"`
108		Root    *bundleRootJSON    `json:"root"`
109		Blocks  *[]bundleBlockJSON `json:"blocks"`
110	}
111	
112	// postBundle handles POST /v1/bundles.
113	func (s *store) postBundle(w http.ResponseWriter, r *http.Request) {
114		if r.Method != http.MethodPost {
115			w.Header().Set("Allow", http.MethodPost)
116			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
117			return
118		}
119		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
120		if err != nil || mediaType != bundleMediaType {
121			writeError(w, http.StatusUnsupportedMediaType, "unsupported_media_type")
122			return
123		}
124		body, err := io.ReadAll(io.LimitReader(r.Body, maxBundleSize+1))
125		if err != nil {
126			writeError(w, http.StatusBadRequest, "invalid_bundle")
127			return
128		}
129		if len(body) > maxBundleSize {
130			writeError(w, http.StatusRequestEntityTooLarge, "payload_too_large")
131			return
132		}
133		obj, code, status := parseBundle(body)
134		if code != "" {
135			writeError(w, status, code)
136			return
137		}
138		stored, created := s.put(obj, auditBundleImport, nil)
139		respStatus := http.StatusOK
140		if created {
141			respStatus = http.StatusCreated
142		}
143		writeJSON(w, respStatus, objectResponse{
144			CID:       stored.cid,
145			Size:      stored.size,
146			ChunkSize: ChunkSize,
147			Chunks:    stored.cids,
148			Created:   created,
149		})
150	}
151	
152	// parseBundle fully validates a bundle body and, on success, returns the
153	// object ready to store. On failure it returns the error code and HTTP
154	// status to report; the store is never touched on the failure path.
155	func parseBundle(body []byte) (obj *object, code string, status int) {
156		invalid := func() (*object, string, int) {
157			return nil, "invalid_bundle", http.StatusBadRequest
158		}
159		integrity := func() (*object, string, int) {
160			return nil, "integrity_check_failed", http.StatusUnprocessableEntity
161		}
162	
163		if !wellFormedJSON(body) {
164			return invalid()
165		}
166		var doc bundleJSON
167		dec := json.NewDecoder(bytes.NewReader(body))
168		dec.DisallowUnknownFields()
169		if err := dec.Decode(&doc); err != nil {
170			return invalid()
171		}
172		if doc.Version == nil || doc.Root == nil || doc.Blocks == nil ||
173			doc.Root.CID == nil || doc.Root.Size == nil || doc.Root.ChunkSize == nil ||
174			doc.Root.Chunks == nil {
175			return invalid()
176		}
177		for _, b := range *doc.Blocks {
178			if b.CID == nil || b.Data == nil {
179				return invalid()
180			}
181		}
182	
183		// Numeric fields must be integers. An integer outside int64 range is a
184		// value problem, not a type problem: it cannot match a supported
185		// version, chunk size or size limit.
186		version, err := parseInt(*doc.Version)
187		if err != nil {
188			if errors.Is(err, strconv.ErrRange) {
189				return nil, "unsupported_bundle", http.StatusUnprocessableEntity
190			}
191			return invalid()
192		}
193		chunkSize, err := parseInt(*doc.Root.ChunkSize)
194		if err != nil {
195			if errors.Is(err, strconv.ErrRange) {
196				return nil, "unsupported_bundle", http.StatusUnprocessableEntity
197			}
198			return invalid()
199		}
200		size, err := parseInt(*doc.Root.Size)
201		if err != nil {
202			if errors.Is(err, strconv.ErrRange) {
203				return nil, "payload_too_large", http.StatusRequestEntityTooLarge
204			}
205			return invalid()
206		}
207	
208		if !validCID(*doc.Root.CID) {
209			return invalid()
210		}
211		for _, c := range *doc.Root.Chunks {
212			if !validCID(c) {
213				return invalid()
214			}
215		}
216		blockData := make(map[string][]byte, len(*doc.Blocks))
217		for _, b := range *doc.Blocks {
218			if !validCID(*b.CID) {
219				return invalid()
220			}
221			data, err := base64.StdEncoding.DecodeString(*b.Data)
222			if err != nil {
223				return invalid()
224			}
225			blockData[*b.CID] = data
226		}
227	
228		if version != bundleVersion || chunkSize != ChunkSize {
229			return nil, "unsupported_bundle", http.StatusUnprocessableEntity
230		}
231		if size > MaxObjectSize {
232			return nil, "payload_too_large", http.StatusRequestEntityTooLarge
233		}
234		if size < 0 {
235			return integrity()
236		}
237	
238		// The block set must be exactly the unique identifiers the manifest
239		// references: no duplicates, none missing, none unreferenced.
240		referenced := make(map[string]bool, len(*doc.Root.Chunks))
241		for _, c := range *doc.Root.Chunks {
242			referenced[c] = true
243		}
244		seen := make(map[string]bool, len(*doc.Blocks))
245		for _, b := range *doc.Blocks {
246			if seen[*b.CID] {
247				return integrity()
248			}
249			seen[*b.CID] = true
250			if !referenced[*b.CID] {
251				return integrity()
252			}
253		}
254		for c := range referenced {
255			if !seen[c] {
256				return integrity()
257			}
258		}
259	
260		// Every block identifier must be the digest of its decoded bytes.
261		for cid, data := range blockData {
262			if chunkCID(data) != cid {
263				return integrity()
264			}
265		}
266	
267		// Rebuild the body in manifest order under the fixed chunking rules:
268		// every chunk but the last is exactly ChunkSize, the last is 1..ChunkSize,
269		// and an empty object carries no chunks at all.
270		chunks := *doc.Root.Chunks
271		if size == 0 && len(chunks) != 0 {
272			return integrity()
273		}
274		if size > 0 && len(chunks) == 0 {
275			return integrity()
276		}
277		total := 0
278		for i, c := range chunks {
279			n := len(blockData[c])
280			if i < len(chunks)-1 {
281				if n != ChunkSize {
282					return integrity()
283				}
284			} else if n < 1 || n > ChunkSize {
285				return integrity()
286			}
287			total += n
288		}
289		if total > MaxObjectSize {
290			return nil, "payload_too_large", http.StatusRequestEntityTooLarge
291		}
292		if total != size {
293			return integrity()
294		}
295		if rootCID(size, chunks) != *doc.Root.CID {
296			return integrity()
297		}
298	
299		obj = &object{
300			cid:    *doc.Root.CID,
301			size:   size,
302			chunks: make([][]byte, 0, len(chunks)),
303			cids:   append([]string{}, chunks...),
304		}
305		for _, c := range chunks {
306			obj.chunks = append(obj.chunks, blockData[c])
307		}
308		return obj, "", 0
309	}
310	
311	// wellFormedJSON reports whether data is a single well-formed JSON value
312	// with no duplicate object keys and nothing but whitespace after it.
313	func wellFormedJSON(data []byte) bool {
314		dec := json.NewDecoder(bytes.NewReader(data))
315		var walk func() bool
316		walk = func() bool {
317			tok, err := dec.Token()
318			if err != nil {
319				return false
320			}
321			delim, ok := tok.(json.Delim)
322			if !ok {
323				return true
324			}
325			switch delim {
326			case '{':
327				seen := make(map[string]bool)
328				for dec.More() {
329					key, err := dec.Token()
330					if err != nil {
331						return false
332					}
333					name, ok := key.(string)
334					if !ok || seen[name] {
335						return false
336					}
337					seen[name] = true
338					if !walk() {
339						return false
340					}
341				}
342				_, err := dec.Token()
343				return err == nil
344			case '[':
345				for dec.More() {
346					if !walk() {
347						return false
348					}
349				}
350				_, err := dec.Token()
351				return err == nil
352			}
353			return false
354		}
355		if !walk() {
356			return false
357		}
358		_, err := dec.Token()
359		return err == io.EOF
360	}
361	
362	// parseInt converts a raw JSON value to an int, rejecting strings,
363	// non-numeric literals and fractional values as syntax errors.
364	func parseInt(raw json.RawMessage) (int, error) {
365		if len(raw) == 0 || raw[0] == '"' {
366			return 0, strconv.ErrSyntax
367		}
368		v, err := strconv.ParseInt(string(raw), 10, 0)
369		if err != nil {
370			return 0, err
371		}
372		return int(v), nil
373	}
