1	package server
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"io"
7		"mime"
8		"net/http"
9		"net/url"
10		"sort"
11		"strings"
12		"sync"
13		"time"
14	)
15	
16	// maxProviderAddresses bounds the addresses one provider record may carry.
17	const maxProviderAddresses = 16
18	
19	// maxProviderBodySize bounds the wire size of a provider publication body.
20	// The protocol itself only bounds the address count; the cap just keeps an
21	// unbounded request from exhausting memory.
22	const maxProviderBodySize = 1 << 20
23	
24	// maxProviderTTL is the longest lifetime a provider record may announce.
25	const maxProviderTTL = 24 * time.Hour
26	
27	// providerRecord is one provider's advertised access locations for a CID.
28	type providerRecord struct {
29		addresses []string
30		expiresAt time.Time
31	}
32	
33	// providerDirectory is a process-local index of provider records keyed by
34	// CID and then provider ID. Publishing a record does not require the object
35	// to be stored locally; the directory takes no part in pinning, garbage
36	// collection or storage statistics, and records are not retained across
37	// restarts.
38	type providerDirectory struct {
39		mu      sync.RWMutex
40		records map[string]map[string]providerRecord
41		audit   *auditLog // nil until wired by the HTTP surface
42	}
43	
44	func newProviderDirectory() *providerDirectory {
45		return &providerDirectory{records: make(map[string]map[string]providerRecord)}
46	}
47	
48	// put publishes or replaces the record for (cid, providerID) and reports
49	// whether a valid record existed at now. A first publication or a
50	// replacement of an expired record reports created == true; exactly one
51	// concurrent first publisher observes it for a given key.
52	func (d *providerDirectory) put(cid, providerID string, addresses []string, expiresAt, now time.Time) (created bool) {
53		d.mu.Lock()
54		defer d.mu.Unlock()
55		byProvider := d.records[cid]
56		if byProvider == nil {
57			byProvider = make(map[string]providerRecord)
58			d.records[cid] = byProvider
59		}
60		existing, found := byProvider[providerID]
61		created = !found || !existing.expiresAt.After(now)
62		byProvider[providerID] = providerRecord{
63			addresses: append([]string(nil), addresses...),
64			expiresAt: expiresAt,
65		}
66		result := "updated"
67		if created {
68			result = "created"
69		}
70		d.audit.append(auditRecord{
71			action:     auditProviderPut,
72			result:     result,
73			cid:        strPtr(cid),
74			providerID: strPtr(providerID),
75		})
76		return created
77	}
78	
79	// providerEntry is one live record in a point-in-time directory listing.
80	type providerEntry struct {
81		providerID string
82		addresses  []string
83		expiresAt  time.Time
84	}
85	
86	// list returns the records valid at now for cid, sorted by provider ID.
87	// The slice and its address arrays are copies, so callers keep a consistent
88	// snapshot even while other requests mutate the directory.
89	func (d *providerDirectory) list(cid string, now time.Time) []providerEntry {
90		d.mu.RLock()
91		defer d.mu.RUnlock()
92		entries := []providerEntry{}
93		for id, rec := range d.records[cid] {
94			if !rec.expiresAt.After(now) {
95				continue
96			}
97			entries = append(entries, providerEntry{
98				providerID: id,
99				addresses:  append([]string(nil), rec.addresses...),
100				expiresAt:  rec.expiresAt,
101			})
102		}
103		sort.Slice(entries, func(i, j int) bool { return entries[i].providerID < entries[j].providerID })
104		return entries
105	}
106	
107	// remove deletes the record for (cid, providerID) when one is in force at
108	// now, reporting whether such a record existed. Expired records are treated
109	// as absent.
110	func (d *providerDirectory) remove(cid, providerID string, now time.Time) bool {
111		d.mu.Lock()
112		defer d.mu.Unlock()
113		byProvider := d.records[cid]
114		rec, found := byProvider[providerID]
115		if !found || !rec.expiresAt.After(now) {
116			return false
117		}
118		delete(byProvider, providerID)
119		if len(byProvider) == 0 {
120			delete(d.records, cid)
121		}
122		d.audit.append(auditRecord{
123			action:     auditProviderDelete,
124			result:     "deleted",
125			cid:        strPtr(cid),
126			providerID: strPtr(providerID),
127		})
128		return true
129	}
130	
131	// providerPutRequest is the strictly decoded body of
132	// PUT /v1/providers/{cid}/{providerId}. Raw pointer fields distinguish a
133	// missing key (nil) from an explicit null and keep type errors distinct
134	// from value errors.
135	type providerPutRequest struct {
136		Addresses *json.RawMessage `json:"addresses"`
137		ExpiresAt *json.RawMessage `json:"expiresAt"`
138	}
139	
140	// providerRecordResponse is the JSON representation of one provider record.
141	type providerRecordResponse struct {
142		ProviderID string    `json:"providerId"`
143		Addresses  []string  `json:"addresses"`
144		ExpiresAt  time.Time `json:"expiresAt"`
145	}
146	
147	// providerListResponse is the JSON body of GET /v1/providers/{cid}.
148	type providerListResponse struct {
149		CID       string                   `json:"cid"`
150		Providers []providerRecordResponse `json:"providers"`
151	}
152	
153	// providersByCID handles GET /v1/providers/{cid}.
154	func (d *providerDirectory) providersByCID(w http.ResponseWriter, r *http.Request) {
155		if r.Method != http.MethodGet {
156			w.Header().Set("Allow", http.MethodGet)
157			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
158			return
159		}
160		cid := r.PathValue("cid")
161		if !validCID(cid) {
162			writeError(w, http.StatusBadRequest, "invalid_cid")
163			return
164		}
165		entries := d.list(cid, time.Now())
166		providers := make([]providerRecordResponse, 0, len(entries))
167		for _, e := range entries {
168			providers = append(providers, providerRecordResponse{
169				ProviderID: e.providerID,
170				Addresses:  e.addresses,
171				ExpiresAt:  e.expiresAt,
172			})
173		}
174		writeJSON(w, http.StatusOK, providerListResponse{CID: cid, Providers: providers})
175	}
176	
177	// providerByID handles PUT and DELETE on /v1/providers/{cid}/{providerId}.
178	func (d *providerDirectory) providerByID(w http.ResponseWriter, r *http.Request) {
179		switch r.Method {
180		case http.MethodPut:
181			d.putProvider(w, r)
182		case http.MethodDelete:
183			d.deleteProvider(w, r)
184		default:
185			w.Header().Set("Allow", "PUT, DELETE")
186			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
187		}
188	}
189	
190	// putProvider handles PUT /v1/providers/{cid}/{providerId}.
191	func (d *providerDirectory) putProvider(w http.ResponseWriter, r *http.Request) {
192		cid := r.PathValue("cid")
193		if !validCID(cid) {
194			writeError(w, http.StatusBadRequest, "invalid_cid")
195			return
196		}
197		providerID := r.PathValue("providerId")
198		if !validProviderID(providerID) {
199			writeError(w, http.StatusBadRequest, "invalid_provider")
200			return
201		}
202		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
203		if err != nil || mediaType != "application/json" {
204			writeError(w, http.StatusUnsupportedMediaType, "unsupported_media_type")
205			return
206		}
207		body, err := io.ReadAll(io.LimitReader(r.Body, maxProviderBodySize+1))
208		if err != nil || len(body) > maxProviderBodySize {
209			writeError(w, http.StatusBadRequest, "invalid_request")
210			return
211		}
212		if !wellFormedJSON(body) {
213			writeError(w, http.StatusBadRequest, "invalid_request")
214			return
215		}
216		var req providerPutRequest
217		dec := json.NewDecoder(bytes.NewReader(body))
218		dec.DisallowUnknownFields()
219		if err := dec.Decode(&req); err != nil {
220			writeError(w, http.StatusBadRequest, "invalid_request")
221			return
222		}
223		if req.Addresses == nil || req.ExpiresAt == nil ||
224			bytes.Equal(bytes.TrimSpace(*req.Addresses), []byte("null")) ||
225			bytes.Equal(bytes.TrimSpace(*req.ExpiresAt), []byte("null")) {
226			writeError(w, http.StatusBadRequest, "invalid_request")
227			return
228		}
229		var rawAddresses []json.RawMessage
230		var expiresAtText string
231		if err := json.Unmarshal(*req.Addresses, &rawAddresses); err != nil {
232			writeError(w, http.StatusBadRequest, "invalid_request")
233			return
234		}
235		addresses := make([]string, len(rawAddresses))
236		for i, raw := range rawAddresses {
237			trimmed := bytes.TrimSpace(raw)
238			if len(trimmed) == 0 || bytes.Equal(trimmed, []byte("null")) || trimmed[0] != '"' {
239				writeError(w, http.StatusBadRequest, "invalid_request")
240				return
241			}
242			if err := json.Unmarshal(trimmed, &addresses[i]); err != nil {
243				writeError(w, http.StatusBadRequest, "invalid_request")
244				return
245			}
246		}
247		if err := json.Unmarshal(*req.ExpiresAt, &expiresAtText); err != nil {
248			writeError(w, http.StatusBadRequest, "invalid_request")
249			return
250		}
251		if !validAddresses(addresses) {
252			writeError(w, http.StatusUnprocessableEntity, "invalid_address")
253			return
254		}
255		now := time.Now()
256		expiresAt, err := time.Parse(time.RFC3339, expiresAtText)
257		if err != nil || !expiresAt.After(now) || expiresAt.After(now.Add(maxProviderTTL)) {
258			writeError(w, http.StatusUnprocessableEntity, "invalid_expiration")
259			return
260		}
261		created := d.put(cid, providerID, addresses, expiresAt, now)
262		status := http.StatusOK
263		if created {
264			status = http.StatusCreated
265		}
266		writeJSON(w, status, providerRecordResponse{
267			ProviderID: providerID,
268			Addresses:  addresses,
269			ExpiresAt:  expiresAt,
270		})
271	}
