	go srv.Serve(ln)
	defer srv.Close()
	conn, err := net.Dial("tcp", ln.Addr().String())
	if err != nil {
		fmt.Println("dial:", err)
		return
	}
	fmt.Fprintf(conn, "GET /v1/gateway/c/a%%zz HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n")
	buf := make([]byte, 256)
	n, _ := conn.Read(buf)
	fmt.Printf("raw server response: %q\n", string(buf[:n]))
	conn.Close()

	// Lone surrogate in JSON string
	var v struct{
		Name string `json:"name"`
	}
	err = json.Unmarshal([]byte(`{"name":"a\ud800b"}`), &v)
	fmt.Printf("lone surrogate: err=%v name=% x runes=%d\n", err, v.Name, len([]rune(v.Name)))

