		if e.Name == nil || e.Type == nil || e.CID == nil {
			return nil, false
		}
		if !validDirectoryName(*e.Name) {
			return nil, false
		}
		// UTF-8 byte order equals code-point order, so the string
		// comparison enforces strictly ascending, unique names.
		if *e.Name <= prev {
			return nil, false
		}
