		if err != nil || seg == "" || seg == "." || seg == ".." ||
			strings.ContainsAny(seg, `/\`) || !utf8.ValidString(seg) {
			writeError(w, http.StatusBadRequest, "invalid_path")
			return
		}
		segments = append(segments, seg)
	}
