func TestGatewayRealServerRawPaths(t *testing.T) {
	ts := httptest.NewServer(Handler())
	defer ts.Close()
	dir := uploadObject(t, Handler(), mustMarshalDir(t, nil))

	for _, p := range []string{
		"/v1/gateway/" + dir.CID + "//x",
		"/v1/gateway/" + dir.CID + "/.",
		"/v1/gateway/" + dir.CID + "/a//b",
		"/v1/gateway/" + dir.CID + "/x%2Fy",
		"/v1/gateway/" + dir.CID + "/%ff",
	} {
		resp, err := http.Get(ts.URL + p)
		if err != nil {
			t.Fatalf("GET %s: %v", p, err)
		}
		body, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		if resp.StatusCode != http.StatusBadRequest {
			t.Fatalf("GET %s: status = %d body = %q, want 400", p, resp.StatusCode, body)
		}
		if !strings.Contains(string(body), "invalid_path") {
			t.Fatalf("GET %s: body = %q, want invalid_path", p, body)
		}
	}

	// Trailing slash is also invalid_path.
	resp, err := http.Get(ts.URL + "/v1/gateway/" + dir.CID + "/")
	if err != nil {
		t.Fatal(err)
	}
	resp.Body.Close()
	if resp.StatusCode != http.StatusBadRequest {
		t.Fatalf("trailing slash status = %d, want 400", resp.StatusCode)
	}

	// Non-GET reaches the wrapper and answers the contract 405.
	req, _ := http.NewRequest(http.MethodPost, ts.URL+"/v1/gateway/"+dir.CID, nil)
	resp, err = http.DefaultClient.Do(req)
	if err != nil {
		t.Fatal(err)
	}
	resp.Body.Close()
	if resp.StatusCode != http.StatusMethodNotAllowed || resp.Header.Get("Allow") != "GET" {
		t.Fatalf("POST status = %d Allow = %q", resp.StatusCode, resp.Header.Get("Allow"))
	}
}
